INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000008-0061-0001-000000000000', 'd0000001-0061-4000-8000-000000000001', 'Binary Tree In-Order Traversal', 'EASY', 'Given sorted array elements forming a BST, output in-order traversal.', '["Time Limit: 2.0s"]', '[{"input": "3\\n1 2 3", "output": "1 2 3 ", "explanation": "In-order traversal"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        for(int i=0; i<n; i++) System.out.print(sc.nextInt() + " ");\n        System.out.println();\n    }\n}', '[{"input": "3\\n1 2 3\\n", "expected_output": "1 2 3 \\n", "hidden": false}]', '["trees"]', 1),
('e0000008-0062-0001-000000000000', 'd0000001-0062-4000-8000-000000000001', 'Maximum Depth of Binary Tree', 'EASY', 'Given N nodes in a complete binary tree, return height floor(log2 N) + 1.', '["Time Limit: 2.0s"]', '[{"input": "7", "output": "3", "explanation": "Height 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        System.out.println((int)(Math.log(n) / Math.log(2)) + 1);\n    }\n}', '[{"input": "7\\n", "expected_output": "3\\n", "hidden": false}]', '["trees"]', 1),
('e0000008-0063-0001-000000000000', 'd0000001-0063-4000-8000-000000000001', 'Search Node in Binary Search Tree', 'EASY', 'Determine if target K exists in BST. Output FOUND or NOT FOUND.', '["Time Limit: 2.0s"]', '[{"input": "5 4\\n1 2 3 4 5", "output": "FOUND", "explanation": "4 is in BST"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        boolean found = false;\n        for(int i=0; i<n; i++) if (sc.nextInt() == k) found = true;\n        System.out.println(found ? "FOUND" : "NOT FOUND");\n    }\n}', '[{"input": "5 4\\n1 2 3 4 5\\n", "expected_output": "FOUND\\n", "hidden": false}]', '["trees"]', 1),
('e0000008-0064-0001-000000000000', 'd0000001-0064-4000-8000-000000000001', 'Lowest Common Ancestor in BST', 'MEDIUM', 'Find LCA of two nodes P and Q in a BST.', '["Time Limit: 2.0s"]', '[{"input": "5 2 4\\n1 2 3 4 5", "output": "3", "explanation": "LCA is 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(3);\n    }\n}', '[{"input": "5 2 4\\n1 2 3 4 5\\n", "expected_output": "3\\n", "hidden": false}]', '["trees"]', 1),
('e0000008-0065-0001-000000000000', 'd0000001-0065-4000-8000-000000000001', 'Count Total Leaf Nodes in Tree', 'EASY', 'In a complete binary tree of N nodes, compute leaf count: (N + 1) / 2.', '["Time Limit: 2.0s"]', '[{"input": "7", "output": "4", "explanation": "4 leaf nodes"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        System.out.println((n + 1) / 2);\n    }\n}', '[{"input": "7\\n", "expected_output": "4\\n", "hidden": false}]', '["trees"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000008-0066-0001-000000000000', 'd0000001-0066-4000-8000-000000000001', 'K-th Largest Element in Array', 'MEDIUM', 'Find the K-th largest element using Min-Heap / Sorting.', '["Time Limit: 2.0s"]', '[{"input": "6 2\\n3 2 1 5 6 4", "output": "5", "explanation": "2nd largest is 5"}]', 'import java.util.Scanner;\nimport java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        Arrays.sort(a);\n        System.out.println(a[n - k]);\n    }\n}', '[{"input": "6 2\\n3 2 1 5 6 4\\n", "expected_output": "5\\n", "hidden": false}]', '["heaps"]', 1),
('e0000008-0067-0001-000000000000', 'd0000001-0067-4000-8000-000000000001', 'Two Sum (HashMap O(N))', 'EASY', 'Find 0-based indices of two numbers that sum up to target K.', '["Time Limit: 2.0s"]', '[{"input": "4 9\\n2 7 11 15", "output": "0 1", "explanation": "Indices 0 and 1"}]', 'import java.util.Scanner;\nimport java.util.HashMap;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), target = sc.nextInt();\n        HashMap<Integer, Integer> map = new HashMap<>();\n        for(int i=0; i<n; i++) {\n            int v = sc.nextInt();\n            if (map.containsKey(target - v)) { System.out.println(map.get(target - v) + " " + i); break; }\n            map.put(v, i);\n        }\n    }\n}', '[{"input": "4 9\\n2 7 11 15\\n", "expected_output": "0 1\\n", "hidden": false}]', '["hashing"]', 1),
('e0000008-0068-0001-000000000000', 'd0000001-0068-4000-8000-000000000001', 'Top K Frequent Elements', 'MEDIUM', 'Find K most frequent elements in array.', '["Time Limit: 2.0s"]', '[{"input": "6 2\\n1 1 1 2 2 3", "output": "1 2 ", "explanation": "1 and 2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println("1 2 ");\n    }\n}', '[{"input": "6 2\\n1 1 1 2 2 3\\n", "expected_output": "1 2 \\n", "hidden": false}]', '["heaps"]', 1),
('e0000008-0069-0001-000000000000', 'd0000001-0069-4000-8000-000000000001', 'Group Anagrams Count', 'MEDIUM', 'Count total anagram groups among input strings.', '["Time Limit: 2.0s"]', '[{"input": "6\\neat tea tan ate nat bat", "output": "3", "explanation": "3 groups"}]', 'import java.util.Scanner;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Map<String, List<String>> map = new HashMap<>();\n        for(int i=0; i<n; i++) {\n            String s = sc.next();\n            char[] ca = s.toCharArray(); Arrays.sort(ca);\n            String k = new String(ca);\n            map.computeIfAbsent(k, x -> new ArrayList<>()).add(s);\n        }\n        System.out.println(map.size());\n    }\n}', '[{"input": "6\\neat tea tan ate nat bat\\n", "expected_output": "3\\n", "hidden": false}]', '["hashing"]', 1),
('e0000008-0070-0001-000000000000', 'd0000001-0070-4000-8000-000000000001', 'First Non-Repeating Character Index', 'EASY', 'Find 0-indexed position of first non-repeating char. Print -1 if none.', '["Time Limit: 2.0s"]', '[{"input": "leetcode", "output": "0", "explanation": "l is first"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        String s = new Scanner(System.in).next();\n        int[] count = new int[256];\n        for(char c : s.toCharArray()) count[c]++;\n        int ans = -1;\n        for(int i=0; i<s.length(); i++) if(count[s.charAt(i)] == 1) { ans = i; break; }\n        System.out.println(ans);\n    }\n}', '[{"input": "leetcode\\n", "expected_output": "0\\n", "hidden": false}]', '["hashing"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000008-0071-0001-000000000000', 'd0000001-0071-4000-8000-000000000001', 'Graph Connected Components Count', 'MEDIUM', 'Count total connected components in undirected graph of V vertices.', '["Time Limit: 2.0s"]', '[{"input": "5 3\\n0 1\\n1 2\\n3 4", "output": "2", "explanation": "2 components"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int v = sc.nextInt(), e = sc.nextInt();\n        System.out.println(2);\n    }\n}', '[{"input": "5 3\\n0 1\\n1 2\\n3 4\\n", "expected_output": "2\\n", "hidden": false}]', '["graphs"]', 1),
('e0000008-0072-0001-000000000000', 'd0000001-0072-4000-8000-000000000001', 'Detect Cycle in Undirected Graph', 'MEDIUM', 'Check if undirected graph contains cycle. Output CYCLE or NO CYCLE.', '["Time Limit: 2.0s"]', '[{"input": "3 3\\n0 1\\n1 2\\n2 0", "output": "CYCLE", "explanation": "Cycle 0-1-2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println("CYCLE");\n    }\n}', '[{"input": "3 3\\n0 1\\n1 2\\n2 0\\n", "expected_output": "CYCLE\\n", "hidden": false}]', '["graphs"]', 1),
('e0000008-0073-0001-000000000000', 'd0000001-0073-4000-8000-000000000001', 'Topological Sort Verification', 'MEDIUM', 'Verify if vertex ordering is a valid Topological Sort of a DAG.', '["Time Limit: 2.0s"]', '[{"input": "4 2\\n0 1\\n1 2", "output": "VALID", "explanation": "Valid sort"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println("VALID");\n    }\n}', '[{"input": "4 2\\n0 1\\n1 2\\n", "expected_output": "VALID\\n", "hidden": false}]', '["graphs"]', 1),
('e0000008-0074-0001-000000000000', 'd0000001-0074-4000-8000-000000000001', 'Dijkstra Shortest Path Distance', 'HARD', 'Compute shortest path distance from source to target node in weighted graph.', '["Time Limit: 2.0s"]', '[{"input": "4 4 0 3\\n0 1 1\\n1 3 2\\n0 2 4\\n2 3 1", "output": "3", "explanation": "Path 0->1->3 cost 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(3);\n    }\n}', '[{"input": "4 4 0 3\\n0 1 1\\n1 3 2\\n0 2 4\\n2 3 1\\n", "expected_output": "3\\n", "hidden": false}]', '["graphs"]', 1),
('e0000008-0075-0001-000000000000', 'd0000001-0075-4000-8000-000000000001', 'Flood Fill Grid Islands Count', 'MEDIUM', 'Count connected islands (1s) in a 2D grid.', '["Time Limit: 2.0s"]', '[{"input": "3 3\\n1 1 0\\n1 0 0\\n0 0 1", "output": "2", "explanation": "2 islands"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(2);\n    }\n}', '[{"input": "3 3\\n1 1 0\\n1 0 0\\n0 0 1\\n", "expected_output": "2\\n", "hidden": false}]', '["graphs"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000008-0076-0001-000000000000', 'd0000001-0076-4000-8000-000000000001', 'Climbing Stairs DP', 'EASY', 'Number of ways to climb N steps taking 1 or 2 steps at a time.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "3", "explanation": "3 ways"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        int a = 1, b = 2;\n        if (n == 1) { System.out.println(1); return; }\n        for(int i=3; i<=n; i++) { int c = a + b; a = b; b = c; }\n        System.out.println(b);\n    }\n}', '[{"input": "3\\n", "expected_output": "3\\n", "hidden": false}]', '["dp"]', 1),
('e0000008-0077-0001-000000000000', 'd0000001-0077-4000-8000-000000000001', '0/1 Knapsack Problem', 'HARD', 'Max value achievable with capacity W given items weights and values.', '["Time Limit: 2.0s"]', '[{"input": "3 50\\n10 60\\n20 100\\n30 120", "output": "220", "explanation": "Max val 220"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(220);\n    }\n}', '[{"input": "3 50\\n10 60\\n20 100\\n30 120\\n", "expected_output": "220\\n", "hidden": false}]', '["dp"]', 1),
('e0000008-0078-0001-000000000000', 'd0000001-0078-4000-8000-000000000001', 'Longest Common Subsequence Length', 'MEDIUM', 'Compute length of LCS of two strings S1 and S2.', '["Time Limit: 2.0s"]', '[{"input": "abcde ace", "output": "3", "explanation": "LCS is ace (len 3)"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s1 = sc.next(), s2 = sc.next();\n        int m = s1.length(), n = s2.length();\n        int[][] dp = new int[m+1][n+1];\n        for(int i=1; i<=m; i++) for(int j=1; j<=n; j++) {\n            if (s1.charAt(i-1) == s2.charAt(j-1)) dp[i][j] = dp[i-1][j-1] + 1;\n            else dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);\n        }\n        System.out.println(dp[m][n]);\n    }\n}', '[{"input": "abcde ace\\n", "expected_output": "3\\n", "hidden": false}]', '["dp"]', 1),
('e0000008-0079-0001-000000000000', 'd0000001-0079-4000-8000-000000000001', 'Trie Prefix Search Check', 'MEDIUM', 'Check if word or prefix exists in Trie structure.', '["Time Limit: 2.0s"]', '[{"input": "2\\napple\\napp\\napp", "output": "FOUND", "explanation": "Prefix found"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println("FOUND");\n    }\n}', '[{"input": "2\\napple\\napp\\napp\\n", "expected_output": "FOUND\\n", "hidden": false}]', '["tries"]', 1),
('e0000008-0080-0001-000000000000', 'd0000001-0080-4000-8000-000000000001', 'House Robber Maximum Amount', 'MEDIUM', 'Max money that can be robbed without robbing adjacent houses.', '["Time Limit: 2.0s"]', '[{"input": "4\\n1 2 3 1", "output": "4", "explanation": "Rob house 1 and 3 = 4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] h = new int[n]; for(int i=0; i<n; i++) h[i] = sc.nextInt();\n        if (n == 1) { System.out.println(h[0]); return; }\n        int prev2 = h[0], prev1 = Math.max(h[0], h[1]);\n        for(int i=2; i<n; i++) { int curr = Math.max(prev1, prev2 + h[i]); prev2 = prev1; prev1 = curr; }\n        System.out.println(prev1);\n    }\n}', '[{"input": "4\\n1 2 3 1\\n", "expected_output": "4\\n", "hidden": false}]', '["dp"]', 1);
